+export class RateLimiter {
+  private hits = new Map<string, number[]>();
+  constructor(private opts: { max: number; windowMs: number }) {}
+
+  private prune(key: string, now: number) {
+    const list = (this.hits.get(key) ?? []).filter(t => now - t < this.opts.windowMs);
+    this.hits.set(key, list);
+    return list;
+  }
+
+  allow(key: string): boolean {
+    return this.prune(key, Date.now()).length < this.opts.max;
+  }
+
+  record(key: string) {
+    this.prune(key, Date.now()).push(Date.now());
+  }
+
+  reset(key: string) {
+    this.hits.delete(key);
+  }
+}
